import React, { useState, useEffect } from 'react';
import { AppConfig } from '../types';
import { saveConfig, applyTheme } from '../services/configService';
import { saveAppConfigToCloud } from '../services/databaseService';

// Import split tab components
import AdminSystemTab from './AdminSystemTab';
import AdminAIExtrasTab from './AdminAIExtrasTab';
import AdminSecurityTab from './AdminSecurityTab';

interface AdminDashboardProps {
  currentConfig: AppConfig;
  onUpdateConfig: (newConfig: AppConfig) => void;
  onExit: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ currentConfig, onUpdateConfig, onExit }) => {
  const [form, setForm] = useState<AppConfig>(currentConfig);
  const [activeTab, setActiveTab] = useState<'system' | 'ai_beauty' | 'security'>('system');
  const [saveStatus, setSaveStatus] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);

  useEffect(() => {
    applyTheme(form.themeColorHex);
  }, [form.themeColorHex]);

  const handleChange = (field: keyof AppConfig, value: any) => {
    setForm(prev => ({ ...prev, [field]: value }));
  };

  const handleSave = async () => {
    setIsSyncing(true);
    setSaveStatus('Đang kết nối Cloud...');

    if (!form.googleScriptUrl || !form.googleScriptUrl.startsWith('https://script.google.com')) {
        setIsSyncing(false);
        setSaveStatus('Lỗi URL');
        alert("Lỗi: URL Google Script không hợp lệ.");
        return;
    }

    saveConfig(form);
    onUpdateConfig(form);

    try {
        const success = await saveAppConfigToCloud(form);
        if (success) setSaveStatus('✔ Đã đồng bộ Cloud');
        else {
            setSaveStatus('⚠️ Đã lưu máy (Lỗi Cloud)');
            alert("Lưu cục bộ thành công nhưng lỗi đồng bộ Cloud.");
        }
    } catch (e) {
        setSaveStatus('❌ Lỗi mạng');
    } finally {
        setIsSyncing(false);
        setTimeout(() => setSaveStatus(''), 5000);
    }
  };

  return (
    <div className="h-full bg-gray-100 dark:bg-gray-950 flex flex-col font-sans overflow-hidden">
      <header className="flex-none bg-white dark:bg-gray-900 border-b border-gray-300 dark:border-gray-800 px-6 py-4 flex justify-between items-center shadow-md z-20">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 bg-brand-600 text-white rounded-xl flex items-center justify-center font-black text-xl shadow-lg shadow-brand-500/30">A</div>
          <div className="leading-tight">
            <h1 className="font-black text-gray-900 dark:text-white text-lg tracking-tight">HỆ THỐNG QUẢN TRỊ</h1>
            <p className="text-[10px] text-brand-600 font-bold uppercase tracking-widest">ID Photo Booth Pro v2.5</p>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <span className={`text-xs font-black transition-all px-3 py-1 rounded-full bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400 ${saveStatus ? 'opacity-100' : 'opacity-0'}`}>{saveStatus}</span>
          <button onClick={onExit} className="px-4 py-2 bg-gray-200 hover:bg-gray-300 dark:bg-gray-800 dark:hover:bg-gray-700 text-gray-800 dark:text-gray-200 rounded-xl text-sm font-bold transition-all flex items-center gap-2 border border-gray-300 dark:border-gray-700 shadow-sm">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"></path></svg> 
            <span>Thoát</span>
          </button>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto bg-gray-100 dark:bg-gray-950">
        <div className="max-w-7xl w-full mx-auto p-6 lg:p-8 grid grid-cols-1 lg:grid-cols-4 gap-8">
          {/* Navigation Sidebar */}
          <nav className="lg:col-span-1 space-y-2">
            {[
              { id: 'system', label: 'Cấu hình hệ thống', icon: '⚙️', desc: 'Shop, Giao diện, Banner' },
              { id: 'ai_beauty', label: 'AI & Làm đẹp', icon: '✨', desc: 'Trang phục, Makeup' },
              { id: 'security', label: 'Bảo mật', icon: '🔒', desc: 'Mật khẩu Admin' }
            ].map(tab => {
              const isActive = activeTab === tab.id;
              return (
                <button 
                  key={tab.id} 
                  onClick={() => setActiveTab(tab.id as any)} 
                  className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl font-bold transition-all duration-300 border-2 text-left ${
                    isActive 
                      ? 'bg-white dark:bg-gray-800 text-brand-600 dark:text-brand-400 border-brand-500 shadow-xl shadow-brand-500/10 scale-[1.02]' 
                      : 'bg-white/50 dark:bg-gray-900/50 border-transparent text-gray-500 dark:text-gray-400 hover:bg-white dark:hover:bg-gray-800'
                  }`}
                >
                  <span className={`text-2xl transition-transform duration-300 ${isActive ? 'scale-110' : ''}`}>{tab.icon}</span> 
                  <div>
                    <div className="text-sm">{tab.label}</div>
                    <div className="text-[10px] font-medium opacity-60">{tab.desc}</div>
                  </div>
                </button>
              )
            })}
          </nav>

          {/* Main Content Area */}
          <div className="lg:col-span-3 space-y-8 pb-32">
            <div className="animate-fadeIn">
                {activeTab === 'system' && (
                  <AdminSystemTab 
                    form={form} 
                    setForm={setForm} 
                    onChange={handleChange} 
                  />
                )}
                {activeTab === 'ai_beauty' && (
                  <AdminAIExtrasTab 
                    form={form} 
                    setForm={setForm} 
                  />
                )}
                {activeTab === 'security' && <AdminSecurityTab form={form} onChange={handleChange} />}
            </div>
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 left-0 right-0 bg-white dark:bg-gray-900 border-t border-gray-300 dark:border-gray-800 p-4 z-50 shadow-[0_-10px_30px_rgba(0,0,0,0.1)]">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-2">
             <div className={`w-2 h-2 rounded-full ${isSyncing ? 'bg-yellow-500 animate-pulse' : 'bg-green-500'}`}></div>
             <span className="text-[10px] font-black text-gray-500 dark:text-gray-400 uppercase tracking-widest">{isSyncing ? 'Đang đồng bộ dữ liệu...' : 'Hệ thống sẵn sàng'}</span>
          </div>
          <button 
            onClick={handleSave} 
            disabled={isSyncing} 
            className={`px-10 py-3.5 rounded-xl font-black text-sm uppercase tracking-wider transition-all shadow-xl active:scale-95 ${
                isSyncing 
                  ? 'bg-gray-300 dark:bg-gray-700 text-gray-500 cursor-not-allowed' 
                  : 'bg-brand-600 hover:bg-brand-700 text-white shadow-brand-500/40'
            }`}
          >
            {isSyncing ? 'Đang Lưu...' : 'Lưu Tất Cả Thay Đổi'}
          </button>
        </div>
      </div>

      <style>{`
        @keyframes fadeIn { from { opacity: 0; transform: translateY(15px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fadeIn { animation: fadeIn 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
      `}</style>
    </div>
  );
};

export default AdminDashboard;

