export default EditorFilterTab;

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BackgroundType, PhotoSettings, PhotoSize, AppConfig, SkinToneType } from '../types';
import { processIDPhoto } from '../services/geminiService';
import { t } from '../services/i18n';

// Sub-components
import EditorBackgroundTab from './EditorBackgroundTab';
import EditorClothingTab from './EditorClothingTab';
import EditorMakeupTab from './EditorMakeupTab';
import EditorFilterTab from './EditorFilterTab';

interface ImageEditorProps {
  originalImage: string;
  settings: PhotoSettings;
  onUpdateSettings: (newSettings: PhotoSettings) => void;
  onProcessedImage: (img: string) => void;
  onNext: () => void;
  onRetake: () => void;
  config: AppConfig;
}

type EditorTab = 'background' | 'beauty' | 'clothing' | 'makeup';

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings, 
  onProcessedImage,
  onNext,
  onRetake,
  config
}) => {
  const [processedUrl, setProcessedUrl] = useState<string>(originalImage);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<EditorTab>('background');
  const [loadingAction, setLoadingAction] = useState<string>('');

  const [sliderPosition, setSliderPosition] = useState(50);
  const imageContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);

  const getAiSettingsHash = useCallback((s: PhotoSettings) => {
    const beauty = s.beauty;
    return JSON.stringify({
       background: s.background,
       cloth: s.clothingPrompt,
       blemish: beauty.blemishIntensity,
       smooth: beauty.smoothSkin,
       lipCol: beauty.lipstickColor,
       lipInt: beauty.lipstickIntensity,
       blushCol: beauty.blushColor,
       blushInt: beauty.blushIntensity,
       brow: beauty.eyebrowIntensity,
       lash: beauty.eyelashIntensity,
       contour: beauty.contourIntensity,
       hair: beauty.hairVolume,
       hairStyle: beauty.hairStyle,
       hairColor: beauty.hairColor 
    });
  }, []);

  const getRawStateHash = useCallback(() => {
     return JSON.stringify({
       background: BackgroundType.ORIGINAL,
       cloth: undefined,
       blemish: 0,
       smooth: 0,
       lipCol: settings.beauty.lipstickColor,
       lipInt: 0,
       blushCol: settings.beauty.blushColor,
       blushInt: 0,
       brow: 0,
       lash: 0,
       contour: 0,
       hair: 0,
       hairStyle: 'original',
       hairColor: 'original'
     });
  }, [settings.beauty.lipstickColor, settings.beauty.blushColor]);

  const [appliedHash, setAppliedHash] = useState<string>(getRawStateHash());

  const hasPendingAiChanges = useMemo(() => {
    const currentHash = getAiSettingsHash(settings);
    const safeAppliedHash = appliedHash || getRawStateHash();
    return currentHash !== safeAppliedHash;
  }, [settings, appliedHash, getAiSettingsHash, getRawStateHash]);

  const handleApplyAiChanges = useCallback(async () => {
    const currentHash = getAiSettingsHash(settings);
    setIsProcessing(true);
    setLoadingAction(t('editor.loading', config));

    try {
      const isDefault = 
        settings.background === BackgroundType.ORIGINAL && 
        !settings.clothingPrompt && 
        settings.beauty.blemishIntensity === 0 && 
        settings.beauty.smoothSkin === 0 &&
        settings.beauty.lipstickIntensity === 0 && 
        settings.beauty.blushIntensity === 0 &&
        settings.beauty.eyebrowIntensity === 0 &&
        settings.beauty.eyelashIntensity === 0 &&
        settings.beauty.contourIntensity === 0 &&
        settings.beauty.hairVolume === 0 &&
        (settings.beauty.hairStyle === 'original' || !settings.beauty.hairStyle) &&
        (settings.beauty.hairColor === 'original' || !settings.beauty.hairColor || settings.beauty.hairColor === 'Màu gốc');

      if (isDefault) {
        setProcessedUrl(originalImage);
      } else {
        const result = await processIDPhoto(
            originalImage, 
            settings.background, 
            settings.clothingPrompt, 
            settings.beauty, 
            settings.size
        );
        setProcessedUrl(result);
      }
      setAppliedHash(currentHash);
    } catch (err: any) {
      console.error(err);
      if (err.message === 'MODEL_NOT_FOUND' || (err.message && err.message.includes('entity was not found'))) {
        alert("Lỗi kết nối AI (404). Vui lòng chọn lại API Key hợp lệ.");
        if ((window as any).aistudio?.openSelectKey) {
            await (window as any).aistudio.openSelectKey();
        }
      } else if (err.message === 'AI_QUOTA_EXCEEDED') {
        alert("Giới hạn lượt dùng AI đã hết. Vui lòng thử lại sau.");
      } else {
        alert("Lỗi xử lý ảnh: " + (err.message || "Không xác định"));
      }
    } finally {
      setIsProcessing(false);
      setLoadingAction('');
    }
  }, [settings, originalImage, getAiSettingsHash, config]);

  const handleBgChange = (bg: BackgroundType) => onUpdateSettings({ ...settings, background: bg });
  const handleClothingClick = (prompt: string) => onUpdateSettings({ ...settings, clothingPrompt: prompt });
  const handleAiBeautyChange = (key: keyof typeof settings.beauty, value: any) => onUpdateSettings({ ...settings, beauty: { ...settings.beauty, [key]: value } });
  const handleClientBeautyChange = (key: keyof typeof settings.beauty, value: any) => onUpdateSettings({ ...settings, beauty: { ...settings.beauty, [key]: value } });

  const imageFilters = useMemo(() => {
    const { lighting, contrast, skinToneIntensity, skinToneType } = settings.beauty;
    const brightnessVal = 100 + (lighting * 1.5); 
    const contrastVal = 100 + (contrast * 1.5);
    let sepia = 0, hue = 0, saturate = 100;
    if (skinToneIntensity > 0) {
        if (skinToneType === SkinToneType.TAN) { sepia = skinToneIntensity * 0.3; saturate = 100 - (skinToneIntensity * 0.1); }
        else if (skinToneType === SkinToneType.ROSY) { sepia = skinToneIntensity * 0.15; hue = -10; saturate = 100 + (skinToneIntensity * 0.1); }
        else if (skinToneType === SkinToneType.FAIR) { saturate = 100 - (skinToneIntensity * 0.1); }
    }
    return `brightness(${brightnessVal}%) contrast(${contrastVal}%) saturate(${saturate}%) sepia(${sepia}%) hue-rotate(${hue}deg)`;
  }, [settings.beauty]);

  const handleFinish = () => {
    const finishExport = (imgSrc: string) => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.src = imgSrc;
        img.onload = () => {
            canvas.width = img.width; canvas.height = img.height;
            if (ctx) { ctx.filter = imageFilters; ctx.drawImage(img, 0, 0, canvas.width, canvas.height); onProcessedImage(canvas.toDataURL('image/png', 1.0)); onNext(); }
        };
    };
    if (hasPendingAiChanges) {
        if (confirm("Có thay đổi chưa áp dụng. Áp dụng ngay?")) {
            handleApplyAiChanges().then(() => finishExport(processedUrl));
        } else { finishExport(processedUrl); }
    } else { finishExport(processedUrl); }
  };

  return (
    <div className="flex flex-col-reverse md:flex-row h-[100dvh] w-full bg-gray-100 dark:bg-gray-950 overflow-hidden font-sans pb-safe"
       onMouseUp={() => { isDraggingRef.current = false; }}
       onTouchEnd={() => { isDraggingRef.current = false; }}
    >
      {/* CONTROLS SIDEBAR */}
      <div className="w-full md:w-[420px] bg-white dark:bg-gray-900 shadow-[0_0_50px_rgba(0,0,0,0.15)] z-20 flex flex-col h-[55dvh] md:h-full border-t md:border-t-0 md:border-r border-gray-200 dark:border-gray-800 shrink-0">

        {/* Header */}
        <div className="hidden md:flex p-6 border-b border-gray-100 dark:border-gray-800 justify-between items-center shrink-0">
          <div className="flex flex-col">
              <h2 className="text-xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Xử lý ảnh thẻ</h2>
              <span className="text-[10px] font-bold text-brand-600 uppercase tracking-widest mt-0.5">ID Photo Studio v2.5</span>
          </div>
          <button onClick={onRetake} className="text-xs font-bold text-red-500 hover:text-red-700 transition-colors flex items-center gap-1.5 uppercase tracking-wider">
             <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path></svg>
             Chụp lại
          </button>
        </div>

        {/* Tab Navigation */}
        <div className="px-4 pt-4 pb-2 md:px-6 md:pt-6 shrink-0 border-b border-gray-100 dark:border-gray-800 md:border-none">
          <div className="flex bg-gray-100 dark:bg-gray-800 p-1.5 rounded-2xl gap-1">
            {[
              {id: 'background', label: t('editor.tab.bg', config), icon: '🖼️'},
              {id: 'clothing', label: t('editor.tab.clothing', config), icon: '👔'},
              {id: 'makeup', label: t('editor.tab.makeup', config), icon: '✨'},
              {id: 'beauty', label: t('editor.tab.filter', config), icon: '🎨'}
            ].map((tab) => (
               <button 
                 key={tab.id} 
                 onClick={() => setActiveTab(tab.id as any)} 
                 className={`flex-1 flex flex-col items-center py-2.5 rounded-xl transition-all active:scale-95 ${
                    activeTab === tab.id 
                    ? 'bg-white dark:bg-gray-700 text-brand-700 dark:text-brand-300 shadow-lg' 
                    : 'text-gray-500 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200'
                 }`}
               >
                 <span className="text-lg mb-0.5">{tab.icon}</span>
                 <span className="text-[10px] font-black uppercase tracking-tighter">{tab.label.split('.')[1]}</span>
               </button>
            ))}
          </div>
        </div>

        {/* Scrollable Controls Area */}
        <div className="flex-1 overflow-y-auto p-5 md:p-6 bg-white dark:bg-gray-900 scrollbar-hide">
          {activeTab === 'background' && (
            <EditorBackgroundTab config={config} settings={settings} onBgChange={handleBgChange} />
          )}

          {activeTab === 'clothing' && (
            <EditorClothingTab config={config} settings={settings} onClothingClick={handleClothingClick} />
          )}

          {activeTab === 'makeup' && (
            <EditorMakeupTab config={config} settings={settings} onAiBeautyChange={handleAiBeautyChange} />
          )}

          {activeTab === 'beauty' && (
            <EditorFilterTab settings={settings} onClientBeautyChange={handleClientBeautyChange} />
          )}
        </div>

        {/* Actions Footer */}
        <div className="p-4 md:p-6 border-t border-gray-200 dark:border-gray-800 bg-white dark:bg-gray-900 space-y-3 shrink-0">
          {hasPendingAiChanges && (
            <button onClick={handleApplyAiChanges} disabled={isProcessing} className="w-full py-4 bg-brand-600 hover:bg-brand-700 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl shadow-brand-500/30 active:scale-95 disabled:opacity-50 flex items-center justify-center gap-3">
               {isProcessing ? <div className="w-5 h-5 border-2 border-white/50 border-t-white rounded-full animate-spin"></div> : "✨"} 
               {t('editor.btn.apply_ai', config)}
            </button>
          )}
          <div className="flex gap-4">
            <button onClick={onRetake} className="flex-1 md:hidden py-4 bg-gray-100 dark:bg-gray-800 text-gray-800 dark:text-gray-300 rounded-2xl font-black text-xs uppercase tracking-widest active:scale-95">Chụp lại</button>
            <button onClick={handleFinish} disabled={isProcessing} className="flex-[3] py-4 bg-gray-900 dark:bg-brand-500 text-white rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl active:scale-95 disabled:bg-gray-400 transition-all">
               {t('editor.btn.finish', config)}
            </button>
          </div>
        </div>
      </div>

      {/* IMAGE PREVIEW AREA */}
      <div className="flex-1 bg-gray-200 dark:bg-gray-950 relative flex items-center justify-center p-6 md:p-12 h-[45dvh] md:h-full shrink-0">
        {isProcessing && (
          <div className="absolute inset-0 z-30 bg-black/40 backdrop-blur-md flex flex-col items-center justify-center">
            <div className="bg-white dark:bg-gray-900 p-8 rounded-[2.5rem] shadow-2xl flex flex-col items-center border border-white/10">
              <div className="w-12 h-12 border-4 border-brand-200 dark:border-brand-900 border-t-brand-600 dark:border-t-brand-400 rounded-full animate-spin mb-4"></div>
              <p className="text-gray-900 dark:text-white font-black text-xs uppercase tracking-widest">{loadingAction}</p>
            </div>
          </div>
        )}

        <div ref={imageContainerRef} className="relative shadow-[0_30px_100px_rgba(0,0,0,0.5)] rounded-lg border-8 border-white dark:border-gray-800 bg-white overflow-hidden max-h-full max-w-full cursor-col-resize touch-none"
             style={{ aspectRatio: settings.size === PhotoSize.SIZE_5X5 ? '1/1' : '2/3', height: '100%', maxHeight: '100%' }}
             onMouseDown={() => { isDraggingRef.current = true; }}
             onTouchStart={() => { isDraggingRef.current = true; }}
             onMouseMove={(e) => {
               if (isDraggingRef.current && imageContainerRef.current) {
                  const rect = imageContainerRef.current.getBoundingClientRect();
                  const x = Math.max(0, Math.min(e.clientX - rect.left, rect.width));
                  setSliderPosition((x / rect.width) * 100);
               }
             }}
             onTouchMove={(e) => {
               if (isDraggingRef.current && imageContainerRef.current) {
                  const rect = imageContainerRef.current.getBoundingClientRect();
                  const x = Math.max(0, Math.min(e.touches[0].clientX - rect.left, rect.width));
                  setSliderPosition((x / rect.width) * 100);
               }
             }}
        >
          <img src={originalImage} className="absolute inset-0 w-full h-full object-contain pointer-events-none" />
          <div className="absolute inset-0 w-full h-full pointer-events-none" style={{ clipPath: `inset(0 ${100 - sliderPosition}% 0 0)` }}>
             <img src={processedUrl} className="absolute inset-0 w-full h-full object-contain" style={{ filter: imageFilters }} />
          </div>
          <div className="absolute top-0 bottom-0 w-1 bg-white z-20 shadow-lg" style={{ left: `${sliderPosition}%` }}>
            <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-10 h-10 bg-white rounded-full shadow-2xl flex items-center justify-center border-4 border-brand-500 cursor-grab active:cursor-grabbing">
              <svg className="w-5 h-5 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M8 9l4-4 4 4m0 6l-4 4-4-4"></path></svg>
            </div>
          </div>

          <div className="absolute bottom-4 left-4 text-[9px] font-black text-white bg-black/50 px-3 py-1.5 rounded-full uppercase tracking-widest backdrop-blur-md pointer-events-none border border-white/10">Ảnh Gốc</div>
          <div className="absolute bottom-4 right-4 text-[9px] font-black text-white bg-brand-600/80 px-3 py-1.5 rounded-full uppercase tracking-widest backdrop-blur-md pointer-events-none border border-white/10">Kết quả</div>
        </div>
      </div>
    </div>
  );
};

