            ].map((tab) => (
               <button 
                 key={tab.id} 
                 onClick={() => setActiveTab(tab.id as any)} 
                 className={`flex-1 flex flex-col items-center py-2.5 rounded-xl transition-all active:scale-95 ${
                    activeTab === tab.id 
                    ? 'bg-white dark:bg-gray-700 text-brand-700 dark:text-brand-300 shadow-lg' 
                    : 'text-gray-500 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200'
                 }`}
               >
                 <span className="text-lg mb-0.5">{tab.icon}</span>
                 <span className="text-[10px] font-black uppercase tracking-tighter">{tab.label.split('.')[1]}</span>
               </button>
            ))}
          </div>
        </div>

        {/* Scrollable Controls Area */}
        <div className="flex-1 overflow-y-auto p-5 md:p-6 bg-white dark:bg-gray-900 scrollbar-hide">
          {activeTab === 'background' && (
