                  const x = Math.max(0, Math.min(e.touches[0].clientX - rect.left, rect.width));
                  setSliderPosition((x / rect.width) * 100);
               }
             }}
        >
          <img src={originalImage} className="absolute inset-0 w-full h-full object-contain pointer-events-none" />
          <div className="absolute inset-0 w-full h-full pointer-events-none" style={{ clipPath: `inset(0 ${100 - sliderPosition}% 0 0)` }}>
             <img src={processedUrl} className="absolute inset-0 w-full h-full object-contain" style={{ filter: imageFilters }} />
          </div>
          <div className="absolute top-0 bottom-0 w-1 bg-white z-20 shadow-lg" style={{ left: `${sliderPosition}%` }}>
            <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-10 h-10 bg-white rounded-full shadow-2xl flex items-center justify-center border-4 border-brand-500 cursor-grab active:cursor-grabbing">
              <svg className="w-5 h-5 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M8 9l4-4 4 4m0 6l-4 4-4-4"></path></svg>
